using System.Net;using System.Net.Http.Json;using Backend.Persistence.Data;using Backend.Persistence.Domain;using Microsoft.AspNetCore.Hosting;using Microsoft.AspNetCore.Mvc.Testing;using Microsoft.Extensions.DependencyInjection;using Xunit;
namespace Backend.Persistence.Tests;
public sealed class WorkspaceApiTests:IClassFixture<WorkspaceApiFactory>{readonly WorkspaceApiFactory f;public WorkspaceApiTests(WorkspaceApiFactory f)=>this.f=f;[Fact]public async Task CreateEditAndArchiveWorkspace(){using var c=f.CreateClient();var x=await c.PostAsJsonAsync("/workspaces",new{name="Acme App",platform="github",platform_ref="acme/app"});Assert.Equal(HttpStatusCode.Created,x.StatusCode);var w=await x.Content.ReadFromJsonAsync<WorkspaceResponse>();var u=await c.PatchAsJsonAsync($"/workspaces/{w!.Id}",new{name="Acme Platform"});Assert.Equal(HttpStatusCode.OK,u.StatusCode);var a=await c.PostAsync($"/workspaces/{w.Id}/archive",null);Assert.Equal(HttpStatusCode.OK,a.StatusCode);Assert.Equal("archived",(await a.Content.ReadFromJsonAsync<WorkspaceResponse>())!.Status);}[Fact]public async Task PlatformChangeIsConflictWhenPipelineExists(){long id;await using(var s=f.Services.CreateAsyncScope()){var d=s.ServiceProvider.GetRequiredService<AppDbContext>();var w=new Workspace{Name="Locked",Slug="locked",Platform=WorkspacePlatform.Github,PlatformRef="acme/locked"};d.Add(w);await d.SaveChangesAsync();d.Add(new PipelineInstance{WorkspaceId=w.Id,ExternalRef="1"});await d.SaveChangesAsync();id=w.Id;}using var c=f.CreateClient();var r=await c.PatchAsJsonAsync($"/workspaces/{id}",new{platform="azure_devops",platform_ref="acme/project"});Assert.Equal(HttpStatusCode.Conflict,r.StatusCode);}[Fact]public async Task InvalidCreateReturns422(){using var c=f.CreateClient();var r=await c.PostAsJsonAsync("/workspaces",new{name="",platform="other",platform_ref=""});Assert.Equal((HttpStatusCode)422,r.StatusCode);}[Fact]public async Task UpdateWithNonexistentClientReturns422(){using var c=f.CreateClient();var created=await c.PostAsJsonAsync("/workspaces",new{name="Client Validation",platform="github",platform_ref="acme/client-validation"});var workspace=await created.Content.ReadFromJsonAsync<WorkspaceResponse>();var r=await c.PatchAsJsonAsync($"/workspaces/{workspace!.Id}",new{client_id=long.MaxValue});Assert.Equal((HttpStatusCode)422,r.StatusCode);}}
public sealed class WorkspaceApiFactory:WebApplicationFactory<Program>{readonly string p=Path.Combine(Path.GetTempPath(),$"workspace-api-{Guid.NewGuid():N}.db");protected override void ConfigureWebHost(IWebHostBuilder b)=>b.UseSetting("DatabasePath",p);protected override void Dispose(bool d){base.Dispose(d);if(File.Exists(p))File.Delete(p);}}
public sealed record WorkspaceResponse(long Id,string Name,string Slug,string Platform,string PlatformRef,long? ClientId,string Status,DateTime CreatedAt);